const sessions = $input.first().json;
const stats = $('Get Library Stats').first().json;

// Parse active playback
const playing = [];
if (Array.isArray(sessions)) {
  for (const s of sessions) {
    if (s.NowPlayingItem) {
      const np = s.NowPlayingItem;
      const ps = s.PlayState || {};
      const pos = Math.floor((ps.PositionTicks || 0) / 10000000);
      playing.push({
        device: s.DeviceName,
        title: np.Name,
        artist: (np.Artists || []).join(', '),
        album: np.Album || '',
        type: np.Type === 'Audio' ? 'music' : 'movie',
        paused: ps.IsPaused || false,
        position: `${Math.floor(pos/60)}:${String(pos%60).padStart(2,'0')}`,
      });
    }
  }
}

return [{
  json: {
    now_playing: playing,
    library: {
      tracks: stats.SongCount || 0,
      albums: stats.AlbumCount || 0,
      artists: stats.ArtistCount || 0,
      movies: stats.MovieCount || 0,
    },
    timestamp: new Date().toISOString(),
  }
}];
